// runExplainDefault shows a branch-focused view of all checkpoints on the current branch.
func runExplainDefault(w io.Writer, noPager bool) error {
	strat := GetStrategy()

	// Get rewind points (checkpoints) from the strategy
	rewindPoints, err := strat.GetRewindPoints(100) // Get up to 100 checkpoints
	if err != nil {
		return fmt.Errorf("failed to get checkpoints: %w", err)
	}

	// Get branch info
	repo, err := openRepository()
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	branchName := strategy.GetCurrentBranchName(repo)
	if branchName == "" {
		branchName = "(detached HEAD)"
	}

	// Get main branch for context
	mainBranchHash := strategy.GetMainBranchHash(repo)
	mainBranchName := "main"
	if mainBranchHash == (plumbing.Hash{}) {
		mainBranchName = "(not found)"
	}

	// Get current session for context
	currentSessionID, _ := paths.ReadCurrentSession()

	// Format output
	output := formatBranchOverview(branchName, mainBranchName, currentSessionID, rewindPoints)

	outputExplainContent(w, output, noPager)
	return nil
}

// formatBranchOverview formats the branch-focused checkpoint view.
func formatBranchOverview(branchName, mainBranchName, currentSessionID string, points []strategy.RewindPoint) string {
	var sb strings.Builder

	// Header
	fmt.Fprintf(&sb, "Branch: %s\n", branchName)
	fmt.Fprintf(&sb, "Base: %s\n", mainBranchName)
	if currentSessionID != "" {
		fmt.Fprintf(&sb, "Current session: %s\n", currentSessionID)
	}
	sb.WriteString("\n")

	if len(points) == 0 {
		sb.WriteString("No checkpoints on this branch.\n")
		sb.WriteString("Checkpoints will appear here after you save changes during a Claude session.\n")
		return sb.String()
	}

	fmt.Fprintf(&sb, "Checkpoints: %d\n\n", len(points))

	// Group by date for readability
	var lastDate string
	for _, pt := range points {
		dateStr := pt.Date.Format("2006-01-02")
		if dateStr != lastDate {
			if lastDate != "" {
				sb.WriteString("\n")
			}
			fmt.Fprintf(&sb, "── %s ──\n", dateStr)
			lastDate = dateStr
		}

		// Checkpoint line
		shortID := pt.CheckpointID
		if shortID == "" {
			shortID = pt.ID
		}
		if len(shortID) > 12 {
			shortID = shortID[:12]
		}

		timeStr := pt.Date.Format("15:04")
		msg := pt.Message
		if len(msg) > 50 {
			msg = msg[:47] + "..."
		}

		// Format: [time] [id] message
		fmt.Fprintf(&sb, "  %s  %s  %s\n", timeStr, shortID, msg)

		// Session info (indented)
		if pt.SessionID != "" {
			sessionPrompt := pt.SessionPrompt
			if sessionPrompt == "" {
				sessionPrompt = "(no prompt)"
			}
			if len(sessionPrompt) > 40 {
				sessionPrompt = sessionPrompt[:37] + "..."
			}
			fmt.Fprintf(&sb, "           └─ %s: %s\n", truncateSessionID(pt.SessionID), sessionPrompt)
		}
	}

	sb.WriteString("\n")
	sb.WriteString("Use 'entire explain --checkpoint <ID>' for details.\n")
	sb.WriteString("Use 'entire explain --session <ID>' for session view.\n")

	return sb.String()
}

// truncateSessionID shortens session ID for display (keeps date + first 8 chars of UUID).
func truncateSessionID(sessionID string) string {
	// Session IDs are like "2026-01-22-0bdbfa06-acf1-473a-b3e4-6a03313d1d0e"
	// Keep "2026-01-22-0bdbfa06" (date + first UUID segment)
	if len(sessionID) > 19 {
		return sessionID[:19]
	}
	return sessionID
}
